mapper.update:
update ${msg_table}
set MESSAGE_STATUS_CD = '02',
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
where MESSAGE_STATUS_CD = '01'
	and SEND_TYPE_CD = '${msg_type}'

update ${msg_table}
set MESSAGE_STATUS_CD = '00',
	MOD_DT = SYSTIMESTAMP,
	MOD_ID = #{mod_id}
where MESSAGE_STATUS_CD = '01'
	and SEND_TYPE_CD = '${msg_type}'
